package fr.gemsofrod.encyclopedie.data

/** Traduzioni italiane del nome e dei testi descrittivi dei fossili. */
object FossileTranslationsIt {
    val data: Map<String, FossileTranslation> = mapOf(
        "fossile-ammonite-madagascar" to FossileTranslation(
            nom = "Ammonite del Madagascar",
            descriptionCourte = "Il fossile più emblematico, spirale calcificata di un cefalopode marino scomparso insieme ai dinosauri.",
            descriptionLongue = "Le ammoniti sono cefalopodi marini imparentati con l'attuale nautilus e con il polpo, la cui conchiglia avvolta a spirale si è fossilizzata a milioni lungo le antiche coste del Cretaceo malgascio. Segate e lucidate, rivelano i loro setti interni (suture) in motivi geometrici molto apprezzati sia in decorazione sia nella gioielleria d'ingresso.",
            interetJoaillerie = "Buono: dischi lucidati per pendenti, esemplari interi per la decorazione e per la collezione da principianti"
        ),
        "fossile-ammolite" to FossileTranslation(
            nom = "Ammolite",
            descriptionCourte = "L'unico fossile ufficialmente riconosciuto come gemma, la cui iridescenza rivaleggia con quella dell'opale.",
            descriptionLongue = "L'ammolite proviene da un giacimento unico al mondo, lungo il fiume St. Mary's in Alberta, dove la madreperla di aragonite di alcune ammoniti giganti si è conservata intatta invece di ricristallizzarsi in calcite. Il risultato è un'iridescenza spettacolare, così sottile e fragile da essere quasi sempre protetta da un doppietto o un triplo prima dell'incastonatura. La CIBJO l'ha ufficialmente classificata come gemma organica nel 1981, accanto alla perla, al corallo e all'ambra.",
            interetJoaillerie = "Elevato: cabochon, doppietti e tripli incastonati, molto ricercata per la sua iridescenza paragonabile a quella dell'opale"
        ),
        "fossile-orthocere" to FossileTranslation(
            nom = "Ortocera",
            descriptionCourte = "Un cefalopode dalla conchiglia diritta a forma di cono allungato, lontano antenato del calamaro.",
            descriptionLongue = "A differenza dell'ammonite avvolta a spirale, l'ortocera possedeva una conchiglia conica diritta e settata, all'interno della quale l'animale regolava il proprio galleggiamento come fa ancora oggi il nautilus. Le lastre calcaree marocchine, costellate di sezioni di ortocere e di altri invertebrati marini, sono ampiamente utilizzate per pavimentazioni e oggetti decorativi lucidati.",
            interetJoaillerie = "Moderato: soprattutto decorazione (lastre, lavelli, vassoi) piuttosto che gioielleria"
        ),
        "fossile-goniatite" to FossileTranslation(
