            descriptionCourte = "Il diretto antenato dell'ammonite, riconoscibile per i suoi setti interni a zigzag più semplici.",
            descriptionLongue = "Comparse prima delle ammoniti nel Devoniano, le goniatiti condividono la stessa sagoma a spirale ma presentano linee di sutura interne più semplici, a denti di sega. Il Marocco ne estrae esemplari straordinariamente ben conservati, spesso venduti grezzi o leggermente lucidati per rivelare la conchiglia senza cancellarne il rilievo naturale.",
            interetJoaillerie = "Moderato: pezzi da collezione e pendenti grezzi lucidati"
        ),
        "fossile-trilobite-elrathia" to FossileTranslation(
