            descriptionCourte = "Il trilobite più comunemente ritrovato al mondo, estratto a milioni da un unico giacimento dello Utah.",
            descriptionLongue = "Elrathia kingii è un piccolo trilobite del Cambriano medio, estratto in quantità considerevoli dagli scisti della formazione di Wheeler, nello Utah — un giacimento così produttivo da fornire quasi tutti i trilobiti venduti sul mercato mondiale. La sua caratteristica segmentazione tricefala (capo, torace, pigidio) ne fa un eccellente esemplare didattico per comprendere l'anatomia di questo gruppo di artropodi estinto sin dalla fine del Permiano.",
            interetJoaillerie = "Basso: essenzialmente da collezione, talvolta montato grezzo in un pendente protetto"
        ),
        "fossile-trilobite-phacops" to FossileTranslation(
            nom = "Trilobite Phacops rana",
            descriptionCourte = "Il trilobite prediletto dai collezionisti, celebre per i grandi occhi composti a faccette di calcite.",
            descriptionLongue = "Phacops rana è probabilmente il trilobite più ricercato dai collezionisti per i suoi occhi emisferici prominenti, formati da decine di singole lenti di calcite — uno dei primissimi sistemi ottici complessi dell'evoluzione. I laboratori marocchini di Alnif si sono specializzati nella meticolosa preparazione di questi esemplari, liberati con l'ago pneumatico per rivelare il rilievo completo dell'animale arrotolato su se stesso in posizione di difesa.",
            interetJoaillerie = "Basso: essenzialmente da collezione e decorazione"
        ),
        "fossile-trilobite-calymene" to FossileTranslation(
            nom = "Trilobite Calymene",
            descriptionCourte = "Un trilobite classico e accessibile, spesso trovato arrotolato come un porcellino di terra fossile.",
            descriptionLongue = "Il genere Calymene, ampiamente diffuso nei giacimenti marocchini e a lungo noto in Inghilterra con il soprannome di «Dudley bug», si distingue per la capacità di arrotolarsi completamente su se stesso in posizione difensiva, esattamente come fa oggi un porcellino di terra. Questo comportamento fossilizzato «a palla» è uno degli esemplari introduttivi più comuni per i collezionisti alle prime armi.",
            interetJoaillerie = "Basso: collezione e decorazione"
        ),
        "fossile-dent-megalodon" to FossileTranslation(
            nom = "Dente di megalodonte",
            descriptionCourte = "Il dente del più grande squalo mai esistito, che può superare i 18 cm di altezza.",
            descriptionLongue = "Il megalodonte, squalo gigante estinto circa 3,6 milioni di anni fa, poteva raggiungere i 15-18 metri di lunghezza. I suoi massicci denti triangolari, seghettati come quelli dell'attuale grande squalo bianco ma molto più grandi, si sono mineralizzati nel sedimento assumendo tonalità variabili a seconda dei giacimenti. I pezzi più belli, simmetrici e privi di usura, raggiungono prezzi elevati sia da collezione sia in gioielleria grezza.",
            interetJoaillerie = "Elevato: pendenti grezzi incastonati con artigli, molto richiesti nella gioielleria decorativa"
        ),
        "fossile-os-dinosaure-gembone" to FossileTranslation(
            nom = "Osso di dinosauro agatizzato (\"gembone\")",
            descriptionCourte = "Un osso di dinosauro interamente sostituito, molecola dopo molecola, da agata colorata.",
            descriptionLongue = "In alcuni giacimenti del Giurassico americano, le ossa di dinosauro sepolte hanno subito una completa silicizzazione: la materia ossea originale si è dissolta ed è stata progressivamente sostituita da silice colorata, preservando fedelmente la struttura cellulare porosa dell'osso mentre la trasformava in agata lucidabile. Il risultato, soprannominato «gembone» dai lapidari, unisce il valore scientifico di un autentico fossile di dinosauro al fascino estetico di una pietra semipreziosa dai motivi unici.",
            interetJoaillerie = "Elevato: cabochon molto ricercati, motivo cellulare unico impossibile da imitare"
        ),
        "fossile-poisson-green-river" to FossileTranslation(
            nom = "Pesce fossile di Green River",
            descriptionCourte = "Interi banchi di piccoli pesci fissati in un calcare lacustre di eccezionale finezza.",
            descriptionLongue = "L'antico lago Fossile del Wyoming ha preservato, in sedimenti finemente stratificati, decine di migliaia di pesci d'acqua dolce in uno stato di conservazione eccezionale — squame, pinne e talvolta persino contenuto stomacale intatti. La formazione di Green River è oggi uno dei giacimenti di vertebrati fossili più prolifici al mondo, sfruttato a cielo aperto e venduto in lastre segate per la decorazione.",
            interetJoaillerie = "Moderato: lastre incorniciate, oggetti di decorazione più che gioielli"
        ),
        "fossile-dent-mosasaure" to FossileTranslation(
            nom = "Dente di mosasauro",
            descriptionCourte = "Il dente conico di un grande rettile marino predatore, lontano cugino degli attuali varani.",
            descriptionLongue = "I mosasauri erano grandi rettili marini predatori, imparentati con gli attuali varani, che dominarono i mari nell'estremo finale del Cretaceo, poco prima dell'estinzione che travolse anche i dinosauri non aviani. I fosfati marocchini di Khouribga, rinomati in tutto il mondo per la loro ricchezza in vertebrati marini fossili, restituiscono regolarmente denti conici ben conservati, apprezzati dai collezionisti per la loro forma spettacolare.",
            interetJoaillerie = "Moderato: pendenti grezzi, forte valore da collezione"
        ),
        "fossile-ivoire-mammouth" to FossileTranslation(
            nom = "Avorio fossile di mammut",
            descriptionCourte = "L'avorio di un gigante scomparso dell'ultima era glaciale, liberato dallo scioglimento del permafrost siberiano.",
            descriptionLongue = "Il progressivo riscaldamento del permafrost siberiano libera ogni anno zanne di mammut lanoso, talvolta straordinariamente conservate dopo decine di migliaia di anni di sepoltura nel ghiaccio. Questo commercio, legale e regolamentato a differenza dell'avorio di elefante moderno, rifornisce scultori e gioiellieri di un materiale dalla texture e dalla grana simili all'avorio vivente, talvolta impreziosito da spettacolari tonalità blu-verdi dovute a una mineralizzazione superficiale al fosfato di ferro (vivianite).",
            interetJoaillerie = "Elevato: sculture, gioielli, incrostazioni — commercio legale e regolamentato, a differenza dell'attuale avorio di elefante"
        ),
        "fossile-bois-petrifie" to FossileTranslation(
            nom = "Legno pietrificato",
            descriptionCourte = "Un intero tronco d'albero trasformato in pietra, anello dopo anello, per infiltrazione di silice.",
            descriptionLongue = "Quando un tronco cade e si ritrova rapidamente sepolto in un sedimento saturo di silice, l'acqua ricca di silicati si infiltra progressivamente nella struttura cellulare del legno e la sostituisce, fibra dopo fibra, prima che la decomposizione la cancelli. Il risultato conserva la texture, gli anelli di accrescimento e talvolta persino gli insetti che avevano scavato la corteccia, acquisendo al contempo la durezza e la lucidabilità dell'agata — da cui la sua popolarità tanto in gioielleria quanto nell'arredamento decorativo di grandi dimensioni.",
            interetJoaillerie = "Elevato: cabochon e gioielli, molto richiesto anche in decorazione (vassoi, piani di tavolo)"
        ),
        "fossile-fougere" to FossileTranslation(
            nom = "Felce fossile",
            descriptionCourte = "La delicata impronta carboniosa di una felce delle immense foreste paludose del Carbonifero.",
            descriptionLongue = "Le vaste torbiere forestali del Carbonifero, all'origine della maggior parte dei giacimenti di carbone attuali, hanno lasciato nei loro scisti argillosi innumerevoli impronte di felci e di pteridosperme (felci a seme), conservate sotto forma di una sottile pellicola di carbonio. Queste lastre, ottenute sfaldando la roccia lungo il piano della foglia fossilizzata, rivelano nervature di straordinaria finezza per vegetali vecchi di oltre 300 milioni di anni.",
            interetJoaillerie = "Basso: essenzialmente collezione e decorazione murale incorniciata"
        ),
        "fossile-ambre-baltique" to FossileTranslation(
            nom = "Ambra del Baltico",
            descriptionCourte = "La resina fossilizzata di foreste di conifere scomparse, la più antica gemma organica della gioielleria umana.",
            descriptionLongue = "L'ambra baltica si formò circa 44 milioni di anni fa dalla resina di conifere giganti, oggi estinte, le cui foreste ricoprivano il nord Europa. Trasportata dai corsi d'acqua e poi gettata sulle spiagge del Mar Baltico dopo le tempeste, è lavorata e scambiata dall'umanità sin dall'età del bronzo — le rotte commerciali dell'ambra figurano tra le più antiche vie di scambio documentate d'Europa.",
            interetJoaillerie = "Elevato: gioielleria tradizionale del Nord Europa sin dall'età del bronzo"
        ),
        "fossile-ambre-inclusion" to FossileTranslation(
            nom = "Ambra con inclusione d'insetto",
            descriptionCourte = "Una zanzara, una formica o un fiore fissati per l'eternità in una goccia di resina divenuta pietra.",
            descriptionLongue = "L'ambra domenicana, più giovane e generalmente più trasparente di quella baltica, deve la sua fama alla straordinaria ricchezza delle sue inclusioni: insetti, ragni, piccoli fiori e persino, occasionalmente, piccoli vertebrati vi restano intrappolati con un lusso di dettagli che ha reso questo fossile celebre ben oltre la cerchia dei collezionisti, reso popolare anche dalla finzione narrativa attorno al DNA conservato nell'ambra.",
            interetJoaillerie = "Elevato: ogni inclusione è unica, forte valore aggiunto nella gioielleria da collezione"
        ),
        "fossile-copal" to FossileTranslation(
            nom = "Copale",
            descriptionCourte = "Lo stadio «adolescente» dell'ambra: una resina fossile troppo giovane per essersi completamente polimerizzata.",
            descriptionLongue = "Il copale è una resina vegetale che non ha ancora completato la lenta polimerizzazione chimica che, nell'arco di milioni di anni, trasforma una resina in vera ambra. Più tenero, più solubile nei solventi e spesso più trasparente, viene talvolta venduto abusivamente come ambra — un semplice test all'acetone (che rende il copale appiccicoso in superficie, senza alcun effetto sulla vera ambra) permette di distinguerli.",
            interetJoaillerie = "Moderato: gioielleria artigianale locale, da distinguere chiaramente dall'ambra in una scheda di vendita"
        ),
        "fossile-corail-agatise" to FossileTranslation(
            nom = "Corallo fossile agatizzato",
            descriptionCourte = "Un'intera barriera corallina trasformata in agata, ogni polipo fissato in un fiore di silice.",
            descriptionLongue = "In Florida, antiche barriere coralline si sono ritrovate silicizzate da acque sotterranee ricche di silice, con ogni polipo corallino fedelmente sostituito dalla calcedonio pur conservando la sua caratteristica struttura raggiata. Una volta tagliato a fette e lucidato, il risultato evoca motivi floreali naturali così regolari da essere talvolta scambiati per una creazione artificiale — è stato designato pietra ufficiale dello Stato della Florida nel 1979.",
            interetJoaillerie = "Elevato: cabochon dai motivi floreali unici, apprezzati nella gioielleria regionale e internazionale"
        ),
        "fossile-oursin" to FossileTranslation(
            nom = "Riccio di mare fossile",
            descriptionCourte = "Il guscio calcareo dalla simmetria perfetta di un riccio di mare, a lungo portato come talismano.",
            descriptionLongue = "I gusci (test) dei ricci di mare fossili, con la loro caratteristica simmetria raggiata a cinque bracci, si ritrovano in abbondanza nei calcari cretacei d'Europa e del Nord Africa. Soprannominati «pani di fata» o «pietre di San Pietro» nel folklore europeo, venivano tradizionalmente conservati come portafortuna o protezione domestica ben prima di essere studiati scientificamente.",
            interetJoaillerie = "Da basso a moderato: portato tradizionalmente come pendente grezzo («pietra di San Pietro» o «pane di fata» in Europa)"
        ),
        "fossile-crinoide" to FossileTranslation(
            nom = "Crinoide (entrochi)",
            descriptionCourte = "Gli anelli calcarei impilati dello stelo di un «giglio di mare», un echinoderma fissato e non una pianta.",
            descriptionLongue = "Nonostante il nome fuorviante di «giglio di mare», il crinoide è un animale echinoderma imparentato con il riccio di mare e la stella marina, fissato al fondo marino tramite un lungo stelo articolato. Questo stelo, composto da anelli calcarei impilati come monete, si disarticola facilmente dopo la morte dell'animale e si ritrova in abbondanza in alcuni calcari, formando ciò che i geologi chiamano un calcare a entrochi una volta lucidato in lastra.",
            interetJoaillerie = "Moderato: lastre e oggetti decorativi più che gioielli, talvolta cabochon per gli steli isolati"
        ),
        "fossile-stromatolite" to FossileTranslation(
            nom = "Stromatolite fossile",
            descriptionCourte = "Le più antiche tracce di vita conosciute sulla Terra, costruite strato dopo strato da colonie di batteri.",
            descriptionLongue = "Gli stromatoliti non sono i resti di un organismo individuale, ma strutture sedimentarie laminate, costruite pazientemente strato dopo strato da colonie di cianobatteri che intrappolavano il sedimento e precipitavano carbonato di calcio. Alcuni giacimenti australiani figurano tra le più antiche tracce di vita identificate sulla Terra, con oltre 3,4 miliardi di anni — una testimonianza diretta dei primissimi ecosistemi del pianeta, oggi lucidata in lastre decorative per il suo motivo concentrico unico.",
            interetJoaillerie = "Da basso a moderato: lastre decorative, cabochon occasionali per le varietà silicizzate"
        ),
        "fossile-belemnite" to FossileTranslation(
            nom = "Belemnite",
            descriptionCourte = "Il «rostro» fossilizzato di un calamaro preistorico, a lungo confuso nel folklore con una pietra del fulmine.",
            descriptionLongue = "Ciò che si trova fossilizzato non è l'animale intero ma il suo rostro, una rigida struttura calcarea interna che fungeva da contrappeso e sostegno al corpo molle del cefalopode, cugino estinto degli attuali calamari. La sua forma conica e allungata, spesso confusa dal folklore popolare europeo con una «pietra del fulmine» caduta dal cielo, ne fa un fossile facilmente riconoscibile anche dai non specialisti.",
            interetJoaillerie = "Basso: collezione, pendenti grezzi occasionali"
        )
    )
}
